WITH metrics AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY shipped_date, id) AS seq_no, CUME_DIST() OVER (PARTITION BY status ORDER BY cost DESC NULLS LAST) AS cost_cume_dist, LAST_VALUE(carrier) IGNORE NULLS OVER (PARTITION BY status ORDER BY shipped_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_carrier FROM shipments) SELECT s.id, s.order_id, s.carrier, s.shipped_date, s.delivered_date, s.cost, s.seq_no, s.last_known_carrier, (SELECT MIN(x.cost) FROM shipments x WHERE x.order_id = s.order_id) AS min_shipment_cost FROM metrics s ORDER BY min_shipment_cost DESC
